// Form field that opens the picker. Values live in hidden inputs so the normal FormData save still works.
const PLACE={home:{names:['home'],empty:'Set home / pickup location'},school:{names:['school','schoolAddress'],empty:'Choose school'},area:{names:['area'],empty:'Set service area'}};
function placeBtn(kind,name,sub){return `<button type="button" class="place${name?' set':''}" data-place="${kind}" onclick="pickFor('${kind}')"><span class="place-ic">${icon(kind==='school'?'school':kind==='home'?'home':'pin')}</span><span class="grow"><b>${esc(name||PLACE[kind].empty)}</b><small>${esc(sub||(name?'Tap to change':'Search, use current location or pin on the map'))}</small></span>${icon('chev')}</button>`}
function placeField(kind,v){const lat=v[kind+'Lat'];return placeBtn(kind,v[PLACE[kind].names[0]],kind==='school'?v.schoolAddress:lat?'📍 Pinned on map':'')+[...PLACE[kind].names,kind+'Lat',kind+'Lng'].map(n=>`<input type="hidden" name="${n}" value="${esc(v[n]??'')}">`).join('')}
