// ---- Live map page (both roles) ----
// Parents follow one child at a time: the active trip that child is on, if any.
const childTrip=c=>liveTrips().find(x=>x.d.id===c.driverId&&eligible(c,x.date))||null;
const trackedChild=()=>{const kids=myChildren();return kids.find(c=>c.id===state.trackId)||kids.find(childTrip)||kids[0]||null};
// What the parent's Live page focuses on (null on other pages and for drivers, which keep the all-trips view).
function focus(){if(state.role!=='parent'||state.tab!=='map')return null;const c=trackedChild();if(!c)return null;const x=childTrip(c),r=x?.t.kids[c.id];return {c,x,r,stop:x?nextStop(c,r,x.dir==='toSchool'):null}}
const mapTrips=()=>{const f=focus();return f?(f.x?[f.x]:[]):liveTrips()};
window.trackChild=id=>{state.trackId=id;if(state.tab==='map')render();else go('map')};
function mapPage(){const f=focus(),live=f?!!f.x:liveTrips().length>0;
 const tabs=f?`<div class="kidtabs">${myChildren().map(k=>`<button class="kidtab${k.id===f.c.id?' on':''}" onclick="trackChild(${k.id})">${avatar(k,'sm')}<span>${esc(k.name)}</span>${childTrip(k)?'<i class="livedot"></i>':''}</button>`).join('')}</div>`:'';
 return pageHead(state.role==='parent'?'Live tracking':'Your live location',f?'Tap a child to follow their trip':db?'Location updates every few seconds while the driver app is open':'Demo mode · only syncs between tabs of this browser')+tabs+`<section class="card live-card big">${live?'<span class="livebadge float"><i></i>LIVE</span>':''}<div id="liveMap" class="livemap tall"></div><div id="liveInfo">${liveInfo()}</div></section>`}
// Status card for the followed child: where they are in the trip, distance and rough ETA to the next stop, and the driver.
function childLiveInfo({c,x,r,stop}){
 if(!x)return `<div class="follow">${empty(`${esc(c.name)} has no trip running`,'Tracking starts by itself when the driver taps Start trip.','🛌')}${journey(c,'toSchool')}${journey(c,'toHome')}</div>`;
 const {t,d,dir}=x,toSchool=dir==='toSchool',fresh=t.loc&&Date.now()-t.loc.ts<120000,dest=toSchool?c.school||'school':'home';
 const head=r?.arrived?`${esc(c.name)} arrived at ${esc(dest)} 🎉`:r?.picked?`${esc(c.name)} is on the way to ${esc(dest)}`:`Driver is coming to pick up ${esc(c.name)}`;
 // Straight-line distance × 1.3 for roads, at about 30 km/h in town: a rough estimate, labelled as such.
 const km=stop&&t.loc?metres(t.loc,stop)*1.3/1000:null,eta=km!=null?`${km<1?Math.round(km*1000)+' m':km.toFixed(1)+' km'} to ${stop.label==='home'?'home':esc(stop.label)} · about ${Math.max(1,Math.round(km/30*60))} min`:'';
 return `<div class="follow"><div class="follow-head">${avatar(c,'lg')}<div class="grow"><h2>${head}</h2><p>${eta||(r?.arrived?`Arrived at ${clock(r.arrived)}`:toSchool?'Home → School':'School → Home')}</p></div><span class="fresh ${t.loc?(fresh?'ok':'stale'):''}">${t.loc?(fresh?`<i></i>${ago(t.loc.ts)}`:`⚠ No signal · ${ago(t.loc.ts)}`):'Waiting for GPS…'}</span></div>${journey(c,dir)}
 <div class="drv-row follow-drv">${driverAv(d)}<div class="grow"><b>${esc(d.name)}</b><small>${esc(d.vehicle)} · ${esc(d.plate)}</small></div>${d.phone?`<a class="btn ghost sm" href="tel:${esc(d.phone.replace(/[^\d+]/g,''))}">${icon('phone')}<span>Call</span></a>`:''}</div></div>`}
function liveInfo(){const f=focus();if(f)return childLiveInfo(f);const live=liveTrips();if(!live.length)return empty(state.role==='parent'?'No trip running right now':'You are not on a trip',state.role==='parent'?'Tracking starts automatically when the driver taps Start trip.':'Start a trip from the Trip tab to share your location.');
 return live.map(({t,d,date,dir})=>{const fresh=t.loc&&Date.now()-t.loc.ts<120000,kids=state.role==='parent'?myChildren().filter(c=>c.driverId===d.id&&eligible(c,date)):onBoard(t);
  return `<div class="trip-row"><div class="drv-row">${driverAv(d)}<div class="grow"><b>${esc(d.name)}</b><small>${esc(d.vehicle)} · ${esc(d.plate)} · ${dir==='toSchool'?'Home → School':'School → Home'}</small></div><span class="fresh ${t.loc?(fresh?'ok':'stale'):''}">${t.loc?(fresh?`<i></i>Updated ${ago(t.loc.ts)}`:`⚠ No signal · ${ago(t.loc.ts)}`):'Waiting for GPS…'}</span></div>${state.role==='parent'?`<div class="chips">${kids.map(c=>`<button class="chip" onclick="trackChild(${c.id})" title="Track ${esc(c.name)}">${avatar(c,'xs')}${esc(c.name)}${kidPill(t.kids[c.id],t)}</button>`).join('')}</div>`:`<p class="muted small">${esc(gpsStatus)}</p><p class="muted small">On board: ${kids.map(c=>esc(c.name)).join(', ')||'nobody yet'}</p>`}</div>`}).join('')}
function initMap(){if(!window.L){$('#liveMap').innerHTML='<div class="empty"><b>The map could not load</b><p>Check the internet connection and refresh.</p></div>';return}const map=L.map('liveMap',{zoomControl:false,scrollWheelZoom:false}).setView([3.183,101.507],13);L.control.zoom({position:'bottomright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);liveMap={map,items:{},centred:false};
 // 🏠 / 🏫 pins for the children this user cares about (only those whose locations were picked on the map).
 const f=focus(),kids=f?[f.c]:state.role==='parent'?myChildren():state.children.filter(c=>c.driverId===state.auth.driverId),seen=new Set(),pins=[],pin=(lat,lng,em,tip)=>{const k=`${em}${lat},${lng}`;if(!lat||seen.has(k))return;seen.add(k);pins.push([lat,lng]);L.marker([lat,lng],{icon:L.divIcon({className:'placepin',html:em,iconSize:[32,32],iconAnchor:[16,16]})}).bindTooltip(tip,{direction:'top',offset:[0,-14]}).addTo(map)};
 for(const c of kids){pin(c.homeLat,c.homeLng,'🏠',`${esc(c.name)}'s pickup`);pin(c.schoolLat,c.schoolLng,'🏫',esc(c.school))}
 // No van to follow yet: frame the child's home and school instead.
 if(!mapTrips().some(x=>x.t.loc)&&pins.length)pins.length===1?map.setView(pins[0],15):map.fitBounds(pins,{padding:[40,40],maxZoom:16});
 updateMap()}
function updateMap(){if(!liveMap)return;const {map,items}=liveMap,live=mapTrips().filter(x=>x.t.loc),keys=live.map(x=>x.key),f=focus();
 // Dashed pointer from the followed child's van to their next stop.
 const van=f?.x?.t.loc,stop=f?.stop,dash=van&&stop?[[van.lat,van.lng],[stop.lat,stop.lng]]:null;
 if(dash){if(liveMap.dash)liveMap.dash.setLatLngs(dash);else liveMap.dash=L.polyline(dash,{color:'#0b7f86',weight:4,opacity:.9,dashArray:'1 10',lineCap:'round'}).addTo(map)}else if(liveMap.dash){liveMap.dash.remove();liveMap.dash=null}
 for(const k of Object.keys(items))if(!keys.includes(k)){items[k].marker.remove();items[k].line.remove();delete items[k]}
 for(const {key,t,d} of live){const pos=[t.loc.lat,t.loc.lng],trail=[...t.path.map(p=>[p.lat,p.lng]),pos];
  if(items[key]){items[key].marker.setLatLng(pos);items[key].line.setLatLngs(trail)}
  else items[key]={line:L.polyline(trail,{color:'#0ea5a0',weight:6,opacity:.85,lineCap:'round'}).addTo(map),marker:L.marker(pos,{icon:L.divIcon({className:'buspin',html:'<span class="pulse"></span><span class="bus">🚐</span>',iconSize:[48,48],iconAnchor:[24,24]})}).bindTooltip(esc(d.name),{direction:'top',offset:[0,-20]}).addTo(map)}}
 if(!live.length)return;const points=live.map(x=>[x.t.loc.lat,x.t.loc.lng]);
 if(!liveMap.centred){liveMap.centred=true;dash?map.fitBounds(dash,{padding:[60,60],maxZoom:16}):points.length===1?map.setView(points[0],16):map.fitBounds(points,{padding:[40,40]})}else if(points.length===1&&!map.getBounds().contains(points[0]))map.panTo(points[0])}

// ---- Driver GPS: shared only while the driver has an active trip ----
function startGPS(key){gpsKey=key;if(geoWatch!==null)return;if(!window.isSecureContext){gpsStatus='Live location needs HTTPS or localhost.';return}if(!navigator.geolocation){gpsStatus='GPS is not available on this device.';return}gpsStatus='Waiting for GPS… allow location access when asked.';geoWatch=navigator.geolocation.watchPosition(onPosition,e=>{gpsStatus='GPS error: '+e.message+(e.code===1?' — allow location access for this site.':'');refreshLive()},{enableHighAccuracy:true,maximumAge:5000,timeout:30000})}
function stopGPS(){if(geoWatch!==null)navigator.geolocation.clearWatch(geoWatch);geoWatch=null;gpsKey=null;gpsStatus=''}
function resumeGPS(){const live=state.role==='driver'&&state.auth?liveTrips()[0]:null;if(live&&(geoWatch===null||gpsKey!==live.key))startGPS(live.key);else if(!live&&geoWatch!==null)stopGPS()}
function onPosition(p){const t=state.trips[gpsKey];if(!t?.active){stopGPS();return}const now=Date.now(),loc={lat:+p.coords.latitude.toFixed(6),lng:+p.coords.longitude.toFixed(6),acc:Math.round(p.coords.accuracy),ts:now};
 gpsStatus=`📡 Sharing live location with parents · accurate to ±${loc.acc} m`;
 if(now-lastSent>=4000){lastSent=now;t.loc=loc;cloud(`trips/${gpsKey}/loc`,loc);const path=t.path||(t.path=[]),last=path[path.length-1];if(!last||metres(last,loc)>=25){const pt={lat:loc.lat,lng:loc.lng,ts:now};path.push(pt);cloudPush(`trips/${gpsKey}/path`,pt)}save()}
 refreshLive()}

// ---- Actions ----
window.setDate=v=>act(()=>{state.selectedDate=v});window.setDriver=v=>act(()=>{if(Number(v)!==state.auth?.driverId)throw Error('You cannot access another driver account.');state.activeDriver=state.auth.driverId});window.setDirection=v=>act(()=>{state.direction=v});
window.editChild=id=>act(()=>{if(state.role!=='parent'||(id&&!myChildren().some(c=>c.id===id)))throw Error('Not your child profile.');state.editId=id;go('editChild')});
window.saveChild=e=>{e.preventDefault();act(()=>{let f=new FormData(e.target),selected=f.getAll('days'),num=k=>f.get(k)?Number(f.get(k)):null;if(!String(f.get('home')||'').trim())throw Error('Set the home / pickup location.');if(!String(f.get('school')||'').trim())throw Error('Choose the school.');if(!selected.length)throw Error('Choose at least one school day.');let id=state.editId||Math.max(0,...state.children.map(c=>c.id))+1;let d=driver(f.get('driverId'));if(!d)throw Error('Choose a driver.');let assigned=state.children.filter(c=>c.id!==id&&c.driverId===d.id&&c.days.some(day=>selected.includes(day)));if(assigned.length>=d.seats)throw Error('Selected driver is at capacity for overlapping school days.');let previous=state.children.find(c=>c.id===id);let record={id,parentId:state.auth.parentId,name:String(f.get('name')).trim(),school:String(f.get('school')).trim(),home:String(f.get('home')).trim(),schoolAddress:String(f.get('schoolAddress')).trim(),homeLat:num('homeLat'),homeLng:num('homeLng'),schoolLat:num('schoolLat'),schoolLng:num('schoolLng'),session:f.get('session')||'morning',pickup:f.get('pickup'),returnPickup:f.get('returnPickup'),driverId:d.id,days:selected,absentDates:previous?.absentDates||[]};let saved=previous?Object.assign(previous,record):record;if(!previous)state.children.push(record);cloud(`children/${id}`,saved);notify(`${record.name}'s schedule and driver saved.`);formDirty=false;state.tab='children'})};
window.deleteChild=async id=>{const c=myChildren().find(x=>x.id===id);if(!c)return;if(Object.values(state.trips).some(t=>t.active&&t.kids?.[id]?.picked&&!t.kids[id].arrived))return toast(`${c.name} is on board right now. Try again after arrival.`,'err');
 if(!await ask({title:`Remove ${c.name}?`,text:`${c.name} will be taken off ${driver(c.driverId)?.name||'the driver'}'s roster. This cannot be undone.`,yes:'Yes, remove',no:'No',danger:true,ic:'trash'}))return;
 act(()=>{state.children=state.children.filter(x=>x.id!==id);cloud(`children/${id}`,null);notify(`${c.name} was removed from AnakGo.`);state.tab='children'})};
window.absence=async id=>{const c=myChildren().find(x=>x.id===id);if(!c)return;const drv=driver(c.driverId)?.name||'The driver',when=fmtDate(state.selectedDate);
 const q=c.absentDates.includes(state.selectedDate)?{title:`Cancel ${c.name}'s absence?`,text:`${drv} will pick up ${c.name} again on ${when}.`,yes:'Yes, cancel it'}:{title:`Mark ${c.name} absent?`,text:`${drv} will not pick up ${c.name} on ${when}. You can cancel this later.`,yes:'Yes, absent'};
 if(await ask({...q,no:'No',ic:'calendar'}))absent(id)};
const absent=id=>act(()=>{let c=myChildren().find(x=>x.id===id);if(!c)throw Error('Not your child profile.');let r=state.trips[tripKey(c.driverId)]?.kids?.[id];if(r?.picked&&!r.arrived)throw Error('Cannot mark absent while the child is on board.');if(c.absentDates.includes(state.selectedDate))c.absentDates=c.absentDates.filter(x=>x!==state.selectedDate);else c.absentDates.push(state.selectedDate);cloud(`children/${id}`,c);notify(`${c.name}: ${c.absentDates.includes(state.selectedDate)?'absent':'absence cancelled'} for ${state.selectedDate}. Driver roster updated.`)});
window.startTrip=async()=>{const r=roster(),toSchool=state.direction==='toSchool';if(r.length&&!await ask({title:`Start trip ${toSchool?'to school':'home'}?`,text:`${r.length} student${r.length===1?'':'s'} on today's list. Parents will see your live location until you finish the trip.`,yes:'Yes, start',no:'No',ic:'play'}))return;beginTrip()};
const beginTrip=()=>act(()=>{if(state.role!=='driver'||state.activeDriver!==state.auth?.driverId)throw Error('Driver login required.');let d=driver(state.activeDriver),r=roster(),key=tripKey(state.activeDriver);if(!r.length)throw Error('No expected students for this driver and date.');if(r.length>d.seats)throw Error('Roster exceeds registered vehicle capacity.');if(liveTrips().length)throw Error('Finish your other active trip first.');if(state.trips[key]?.completed)throw Error('This trip is already completed.');let t={active:true,completed:false,startedAt:Date.now(),kids:{},path:[],loc:null};state.trips[key]=t;cloud(`trips/${key}`,t);startGPS(key);notify(`${d.name} started the ${state.direction==='toSchool'?'home-to-school':'school-to-home'} trip on ${state.selectedDate}. Live tracking is on.`)});
function tripChild(id){if(state.role!=='driver'||state.activeDriver!==state.auth?.driverId)throw Error('Driver login required.');let t=trip(),c=state.children.find(x=>x.id===id);if(!t?.active)throw Error('Start the trip first.');if(!c||c.driverId!==state.activeDriver||!eligible(c))throw Error('This child is not on this trip.');return {t,c,key:tripKey(state.activeDriver)}}
window.pickUp=id=>act(()=>{let {t,c,key}=tripChild(id),d=driver(state.activeDriver);if(t.kids[id]?.picked)throw Error(`${c.name} is already picked up.`);if(onBoard(t).length>=d.seats)throw Error('Vehicle seat capacity reached.');let r={picked:Date.now()};t.kids[id]=r;cloud(`trips/${key}/kids/${id}`,r);notify(`${c.name} was picked up by ${d.name} at ${clock(r.picked)}.`)});
window.arrive=id=>act(()=>{let {t,c,key}=tripChild(id),r=t.kids[id];if(!r?.picked)throw Error(`${c.name} has not been picked up yet.`);if(r.arrived)throw Error(`${c.name} has already arrived.`);r.arrived=Date.now();cloud(`trips/${key}/kids/${id}`,r);notify(`${c.name} arrived at ${state.direction==='toSchool'?'school':'home'} at ${clock(r.arrived)}.`)});
// Undo a mistaken tap: Arrived goes back to On board, Picked up goes back to Waiting. Parents get a correction alert.
window.undoKid=async id=>{const t=trip(),c=state.children.find(x=>x.id===id),r=t?.kids?.[id];if(!t?.active||!r||!c)return;const what=r.arrived?'arrival':'pickup';
 if(!await ask({title:`Undo ${c.name}'s ${what}?`,text:r.arrived?`${c.name} will show as on board again.`:`${c.name} will show as waiting for pickup again.`,yes:'Yes, undo',no:'No',ic:'back'}))return;
 act(()=>{const {t,c,key}=tripChild(id),r=t.kids[id];if(!r)throw Error('Nothing to undo.');if(r.arrived){delete r.arrived;cloud(`trips/${key}/kids/${id}`,r)}else{delete t.kids[id];cloud(`trips/${key}/kids/${id}`,null)}notify(`Correction: ${c.name}'s ${what} was undone by the driver.`)})};
window.allArrived=async()=>{const on=onBoard(trip());if(!on.length)return toast('Nobody is on board.','err');if(!await ask({title:'Everyone arrived?',text:`Mark ${on.map(c=>c.name).join(', ')} as arrived at ${state.direction==='toSchool'?'school':'home'}. Parents will be notified.`,yes:'Yes, all arrived',no:'No',ic:'flag'}))return;
 act(()=>{let t=trip(),key=tripKey(state.activeDriver),on=onBoard(t);if(!t?.active)throw Error('No active trip.');let now=Date.now();for(let c of on){t.kids[c.id].arrived=now;cloud(`trips/${key}/kids/${c.id}`,t.kids[c.id]);notify(`${c.name} arrived at ${state.direction==='toSchool'?'school':'home'} at ${clock(now)}.`)}})};
window.finishTrip=async()=>{let t=trip();if(!t?.active)return toast('No active trip.','err');let on=onBoard(t);if(on.length)return toast(`${on.map(c=>c.name).join(', ')} still on board. Mark them Arrived first.`,'err');
 let missing=roster().filter(c=>!t.kids[c.id]?.picked);if(missing.length&&!await ask({title:'Finish without everyone?',text:`${missing.map(c=>c.name).join(', ')} ${missing.length===1?'was':'were'} not picked up. Finish the trip anyway?`,yes:'Yes, continue',no:'No',ic:'alert'}))return;
 if(!await ask({title:'Vehicle safety check',text:'Walk through the whole vehicle before finishing. Look under and between every seat.',check:'I have checked every seat and no child is left inside',yes:'Finish trip',no:'Not yet',ic:'shield'}))return;
 act(()=>{let t=trip(),key=tripKey(state.activeDriver);if(!t?.active)throw Error('No active trip.');Object.assign(t,{active:false,completed:true,physicalCheck:true,finishedAt:Date.now()});if(db)synced(db.child(`trips/${key}`).update({active:false,completed:true,physicalCheck:true,finishedAt:t.finishedAt}));stopGPS();notify(`${driver(state.activeDriver).name} completed the trip with a physical vehicle check (${state.selectedDate}). Live tracking ended.`)})};
window.previewPhoto=input=>{let f=input.files?.[0];if(f)$('#photoPreview').textContent=`Selected: ${f.name} (saved after submitting profile)`};
window.saveProfile=e=>{e.preventDefault();if(state.role!=='driver'||state.activeDriver!==state.auth?.driverId)return act(()=>{throw Error('Not authorised.')});let f=new FormData(e.target),file=f.get('photo'),d=driver(state.activeDriver);let update=photo=>act(()=>{let seats=Number(f.get('seats'));let maxAssigned=Math.max(0,...days.map(day=>state.children.filter(c=>c.driverId===d.id&&c.days.includes(day)).length));if(seats<maxAssigned)throw Error(`Capacity cannot be below ${maxAssigned} assigned students on an overlapping school day.`);for(let k of ['name','phone','vehicle','plate','area','type'])d[k]=String(f.get(k)).trim();if(f.get('areaLat')){d.areaLat=Number(f.get('areaLat'));d.areaLng=Number(f.get('areaLng'))}d.seats=seats;d.fee=Number(f.get('fee'));if(photo)d.photo=photo;cloud(`drivers/${d.id}`,d);formDirty=false;notify(`${d.name}'s profile updated.`)});if(file&&file.size){if(file.size>250000) return act(()=>{throw Error('Use a photo smaller than 250 KB.')});let reader=new FileReader();reader.onload=()=>update(reader.result);reader.readAsDataURL(file)}else update(null)};
window.pay=async id=>{const c0=myChildren().find(c=>c.id===id),d0=c0&&driver(c0.driverId);if(c0&&!await ask({title:`Record RM ${d0?.fee||0} payment?`,text:`Monthly fee for ${c0.name} to ${d0?.name||'the driver'}. This only records the payment; no money is transferred.`,yes:'Yes, record',no:'No',ic:'card'}))return;
 act(()=>{let c=myChildren().find(c=>c.id===id);if(!c)throw Error('Not your child profile.');let d=driver(c.driverId),p={child:c.name,driver:d.name,amount:d.fee,date:new Date().toLocaleDateString('en-MY'),ts:Date.now()};state.payments.unshift(p);cloudPush('payments',p);notify(`Monthly payment recorded: ${c.name}, RM ${d.fee}.`)})};

render();
setInterval(refreshLive,5000); // keeps "updated Xs ago" current
if(db)db.on('value',snap=>{const v=snap.val();if(!v?.children||!v?.drivers){seedCloud();return}applyRemote(v);liveUpdate()},e=>{error='Live sync error: '+e.message;render()});
else window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{Object.assign(state,pick(JSON.parse(e.newValue),SHARED));liveUpdate()}catch{}});
